INSERT INTO apps(id,name,url,category,summary_zh,desc_en,featured,offline,publisher,source,listing_url,tags,sort) VALUES(1,'Alergia España','https://alergia.ai/','health','西班牙各城市的即時花粉、空氣品質與紫外線指數，免註冊，適合過敏族','Alergia España is a free web application providing real-time environmental health data for Spain. It offers daily updates on pollen levels, air quality (PM2.5, NO₂, O₃), and UV index by city. Users can consult data without registration, personalized for allergies and health profiles, and choose from a list of Spanish cities.',0,0,NULL,'pd','https://pwa.directory/directory/alergia-espana-alergia-ai','["pollen-levels", "air-quality", "uv-index"]',0);
