INSERT INTO apps(id,name,url,category,summary_zh,desc_en,featured,offline,publisher,source,listing_url,tags,sort) VALUES(64,'bangla calendar','https://sothikbanglacalendar.live/','tool','孟加拉曆，提供每日 tithi、星宿與曆法資訊','A free Bengali (Bangla) calendar PWA offering daily tithi, nakshatra, and panchang calculated using the traditional Bishuddha Siddhanta method — the same reference published Bengali panjikas use. Includes auspicious muhurta timings, daily rashifal, 15-day weather forecasts, and a growing collection',0,1,NULL,'pd','https://pwa.directory/directory/bangla-calendar','["pwa", "installable"]',55);
INSERT INTO apps(id,name,url,category,summary_zh,desc_en,featured,offline,publisher,source,listing_url,tags,sort) VALUES(66,'Battery Status Progressive Web App','https://irekrog.github.io/battery-status-progressive-web-app','tool','在瀏覽器中顯示裝置電池狀態','A small Progressive Web App that displays your device''s battery status in the browser. It reads battery information from the web platform and gives users a quick view of their charge state, and it also serves as a lightweight example of what web apps can access.',0,1,NULL,'pd','https://pwa.directory/directory/battery-status-progressive-web-app','["battery-status", "device-monitoring", "pwa"]',56);
