INSERT INTO apps(id,name,url,category,summary_zh,desc_en,featured,offline,publisher,source,listing_url,tags,sort) VALUES(102,'JavaScript 2 Factor Authenticator','https://mikedombo.github.io/JSOffline2FA','tool','離線計算兩步驟驗證（TOTP）碼的單頁工具','A single web page that uses local JavaScript to calculate time-based one-time password (TOTP) codes for two-factor authentication, and works offline. It acts as a browser-based alternative to authenticator apps like Google Authenticator for users who want to generate 2FA codes without a phone app or sending secrets to any server.',0,1,NULL,'pd','https://pwa.directory/directory/javascript-2-factor-authenticator','["totp", "two-factor-authentication", "security"]',85);
